sub cmdb 
{
    my ( $item, $server ) = @_;

    my $provider = $CMDB_PROVIDER;
    return Rex::Value->new() unless defined $provider;

    my $cache_key = "cmdb/$provider" . ( defined $server ? "/$server" : "" );
    my $cache     = Rex::Config->get_cache;
    my $cached    = $cache ? $cache->get( $cache_key ) : undef;

    if ( defined $cached ) {
        return $cached if !defined $server;
        return $cached->{ $item } if defined $item;
        return $cached->{$_} for values %{$cached};
    }

    my $data = $provider->get_data;

    if ( defined $server ) {
        if ( !defined $item ) {
            $cached = $provider->get_data_for_server( $server );
            $cache  && $cache->set( $cache_key, $cached );
            return Rex::Value->new( $cached );
        }
        else {
            my $value = $cached->{ $item };
            $cache   && $cache->set( "$cache_key/$item", $value );
            return Rex::Value->new( $value );
        }
    }
    else {
        if ( defined $item ) {
            return Rex::Value->new( $data->{ $item } );
        }
        else {
            return Rex::Value->new( $data );
        }
    }
}

