   filename => 'filename',
   mode     => 'r', # or '<'
   type     => 'Local',
 );

 # or shorter
 my $file = Rex::FS::File->new( filename => 'filename' );

 # open a local file in write mode
 my $file = Rex::FS::File->new(
   filename => 'filename',
   mode     => 'w', # or '>'
 );

Allowed modes:

